import{_ as s,O as a,o as r,c as i,a as o,i as n,f as c}from"./chunks/framework.fmIt2z2h.js";const f=JSON.parse('{"title":"D.02　知识、概念、语境与认识位置","description":"","frontmatter":{"title":"D.02　知识、概念、语境与认识位置","xkChars":691,"xkLessons":{"D.02":{"title":"D.02　知识、概念、语境与认识位置","lead":"听懂一个人的经历、证明一个公式、查清某天发生了什么、决定怎样才公平，不能用同一张预测排行榜来替代。认真听取与认真核证可以同时进行：纠正一处日期，不等于取消一个人的讲述资格。","explanation":["原文定位：第4545—4560行；原文锚点 section-d-02；短引文：‘实用、可行动、获得共识和为真也不是同一标准。’。本题源切片逐字另附于source-slice.md，讲解与原文分开。","本节先区分不同认识活动的证明责任。形式推导要公开前提和规则，经验判断要说明观察怎样支持主张，解释性研究要把文本、语境与竞争读法共同检视，规范论证要说明理由及受影响位置。实践和身体经验也可能提供某些处境与技能方面不可替代的材料，但它们不能自动回答所有因果或规范问题。共同要求是使依据与限度可见，而不是把所有知识化约为预测成绩。","证伪、范式和研究纲领被列为不同尺度的批评入口，不应拼成一条看到反例就全部推倒的统一规则。一次局部检验失败可能涉及辅助假设、对象界定、测量或更广理论。要看原主张承诺了什么、哪一部分被材料触及、哪些后续判断依赖它；能局部修订不等于永远可以用补丁保核心，足以触及共享前提时也不能装作仅是小误差。","换问题可以创造有价值的新研究，但必须把任务变化公开。原预测说某指标会下降，结果没有下降，后来转问人们如何理解该指标并得到丰富访谈，新的解释研究可以成立，却不能倒填成旧预测命中。实用是对某种用途的帮助，可行动是能够据此形成行动方案，共识是参与者达成某种一致，为真则关乎相应事实命题是否成立；四者可以相关，却不互相定义。","语言有时不只报告事实，也在合适条件下构成承诺、命名或授予资格。报告要求事实根据，承诺涉及说话者承担什么，授予资格涉及有权位置与规则，命名还要区分只是分析者设置术语还是制度身份真正改变。说出一句话与该行动有效完成之间，须核说话资格、情境、规则和相关条件，不能只做字面识别。","“我同意”可能是当事人的真实表达，但在特定压力、信息不足或权限条件不合时，仍不足以构成有效授权。要分别理解话语意义与检查制度条件，不能从一个字符串直接生成许可。语言失配也可能来自翻译、术语、语境或沟通渠道差异，不能直接诊断人格或智力；若讨论具体语言困难，需相应专业材料与保护，不从听不懂推断人有缺陷。","认识位置影响材料的取得、能提出的问题及谁更容易被相信。某些承担后果的人可能更清楚日常障碍，却缺少安全表达和被记录的机会。改善听取、翻译与安全入口可以使原本不可见的材料进入分析；但必须逐主张核证，不能先验排除被排斥者，也不能赋予其所有事实陈述自动真值特权。尊重主体地位与判断事实真假是可同时承担的责任。","保护性不公开可以与可信核验并存。例如受限材料可在正当范围交可信复核者核查，同时降低公众不能核验部分的公开结论强度。既不能要求把所有敏感细节公开才能承认问题，也不能用保护二字免除任何核验或无限扩大结论。本节与§16.6相接的是安全表达和可追溯复核，不是鼓励隐匿与不受挑战的断言。","不同方法互相纠正仍须保留理论承诺的真实差异。位置影响知识生产，不推出对象完全由任意叙述制造；理由可能进入因果解释，也不让理解意义的任务消失。可靠日期材料可纠正记忆中的日期，而讲述者为什么把经历与某时刻相连、经历对其有何意义仍可研究。承认其讲述地位不保证每一日期准确，纠正日期也不证明其全部经验或表达失去价值。","八个研究入口分别指向经验与推理的依据，科学批评的尺度，实践与问题解决的关系，对象与建构的关系，身体和生活经验，文本语境及理解，语言概念与行动条件，知识生产中的位置与排斥。本节列出休谟、笛卡尔、波普尔、库恩、拉卡托斯、皮尔士、詹姆斯、杜威、胡塞尔、海德格尔、梅洛-庞蒂、狄尔泰、伽达默尔、利科、维特根斯坦、奥斯汀等作为入口；这不是宣称他们观点一致，也不是本文已重建这些作者全部原作。具体作者观点的深入比较还须对应版本与原文，不能用名单填补论证。","最强反方认为保留多种知识责任会变成什么说法都可以。回应是方法不同并不意味着没有标准，而是把批评落到其实际主张：经验事实看材料，形式推论看前提规则，解释看文本语境与竞争读法，规范看理由与受影响位置。另一反方只承认可预测的答案，则会无故抹去有据的文本理解与规范分歧；这并不要求预测评价消失，只是限制其不能代替所有任务。"],"distinctions":[{"leftTitle":"预测表现","leftText":"对未来或未见结果的某类能力评价。","rightTitle":"全部知识价值","rightText":"形式证明、文本理解、规范理由有各自证明职责。"},{"leftTitle":"局部反例","leftText":"触及特定假设、测量或对象范围。","rightTitle":"全理论必然失效","rightText":"须看共享前提与依赖，不能自动扩大。"},{"leftTitle":"说出我同意","leftText":"可以是真实话语表达。","rightTitle":"有效授权","rightText":"还要核压力、信息、权限和适用制度条件。"},{"leftTitle":"认识位置","leftText":"影响材料可及与发言被信任的条件。","rightTitle":"真值特权","rightText":"身份本身不保证每个事实主张正确。"},{"leftTitle":"纠正事实日期","leftText":"据可靠材料修改具体事实判断。","rightTitle":"取消讲述资格与意义","rightText":"没有从局部日期错到全体经验无效的推论。"}],"boundaries":["不能把被排斥者先验视为不可信，也不能免除具体事实核验。","理解语言不替代检查制度条件，语言差异不直接证明人格或智力问题。","保护性不公开须有可信核验及对应结论上限，不构成任意断言豁免。","新任务有价值不让旧预测失败变成功，事实与意义结果可以分别处理。","本讲没有进行真人访谈、能力测评或对所列全部哲学原作作全文历史考证。"],"questions":["为何局部反例不总推翻整套理论？","保护性不公开是否意味着完全不可核？","纠正记忆日期后，意义解释还剩什么？","不同方法互相约束是否表示理论承诺相同？"],"diagramPath":"/reading-assets/S-D-02/figures/section-d-02.png","caseLinks":[{"title":"真实方法规范：口述史尊重叙述者，也允许有据的不同结论","href":"https://oralhistory.org/oha-statement-on-ethics/"}],"caseNotes":[{"title":"真实方法规范：口述史尊重叙述者，也允许有据的不同结论","text":"口述史协会2018年原则体系中，Core Principles第3项说明记忆受变化的个人与社会语境影响，第7—9项要求关注权力差异、免受伤害及公开许可。Statement on Ethics的Using Oral Sources末两段要求忠实尊重叙述语境，同时允许使用者依据准确引用的证据得出不同于叙述者的结论。这里的尊重、保护和事实批评并不互相排斥。","sourceLabel":"Oral History Association官方2018原则及伦理声明","sourceUrl":"https://oralhistory.org/oha-statement-on-ethics/","sourceLocator":"Core Principles第3、7—9项；Statement on Ethics之Using Oral Sources末两段；总页面Adopted October2018","boundary":"只核协会规范与其日期，不证明每项访谈已执行，更不把规范的采纳当作所有记忆陈述为真。","href":"https://oralhistory.org/oha-statement-on-ethics/"}],"sourceRefs":[{"section":"D.02","start_line":4545,"end_line":4560,"startLine":4545,"endLine":4560}],"outputId":"section-d-02","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["先确认当前任务是形式、经验、解释、规范或其他知识活动，并公开相应依据。","反例沿原命题范围和依赖判断影响，不自动全盘推翻，也不以无限补丁逃避。","改变研究问题时保留旧检验结果，新任务成果不得倒填旧成功。","理解话语内容并另核其作为承诺、资格或授权行为的制度条件。","改善材料接近与安全表达，逐条核事实并保留经验意义；不先验失格或自动赋真。"],"teachingExamples":[{"title":"原文条件例展开：日期可纠正，经历仍需听取","text":"假设叙述者记得事件发生于周二，但可靠原始通知和独立记录共同支持周三。可以把日期改为周三，同时保留其对等待、恐惧或理解方式的叙述作为相应经验材料。不能因日期错误宣布一切经历虚构，也不能因尊重经验拒绝更正日期。","assumptions":"沿原文日期与意义区分展开的教学构造；没有真实人物。","boundary":"只有证据真能支持具体日期时才更正，不默认制度记录永远比口述可靠。"},{"title":"教学构造：换问题不能补旧预测","text":"假想团队预告下月漏办率下降，实际未下降；随后访谈揭示大家对提醒的不同理解。访谈可为意义研究提供材料，却不让漏办率预测变成命中。应分别登记原预测结果和新研究问题。","assumptions":"预测和访谈结果均为假设，未实施调查。","boundary":"新研究仍须合格材料、参与授权与分析，不因任务改变自动有结论。"},{"title":"教学构造：一句同意的两层问题","text":"假想参与者准确说出“我同意”，但其被告知不答应就失去必要支持。可以确认发生了这句表达，同时不能只凭文字判定自由有效授权；要查具体压力和适用条件。","assumptions":"完全教学构造，不评判真实关系。","boundary":"不提供法律裁决，具体有效性须相应制度与专业材料。"}],"counterexamples":[{"identity":"source_counterexample","text":"经验叙述有一处日期错，所以这个人没有资格讲述。","effect":"局部事实更正不取消主体地位和经验意义研究。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"弱势位置让全部发言都天然为真。","effect":"改善被听取的条件不等于真值特权，仍逐主张核证。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"研究得到共识且有用，所以事实命题一定真。","effect":"共识、用途与事实真假是不同标准，需相应材料。","sourceIds":["theory"]}],"questionAnswers":[{"question":"为何局部反例不总推翻整套理论？","answer":"要看它触及哪一假设及其依赖；但若触及共同核心前提，影响可扩大。","basis":"本节原文及上述公开推导"},{"question":"保护性不公开是否意味着完全不可核？","answer":"不是，可在保护范围内由可信复核者核验，并限制不能公开支持的结论强度。","basis":"本节原文及上述公开推导"},{"question":"纠正记忆日期后，意义解释还剩什么？","answer":"叙述方式、与其他经历的联系及当事人理解仍可有材料价值，不能由日期修正一并取消。","basis":"本节原文及上述公开推导"},{"question":"不同方法互相约束是否表示理论承诺相同？","answer":"不是，要保留它们对对象、理由、经验与解释的不同承诺，按具体任务交叉检验。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-D-02/figures/section-d-02.png","alt":"不同知识活动，形式／经验／解释，规范各有责任；反例按范围与依赖，新问题≠旧检验成功；语言意义与行为效力，表达同意≠有效授权；改善认识位置，听取／翻译／安全，不先验排除；逐主张核证，不赋自动真值特权，保护可与核验并存；日期可更正，讲述与意义不消失。作者依D.02绘制；不把预测成绩设为全部知识唯一标准，也不把身份设为真值证明。","caption":"作者依D.02绘制；不把预测成绩设为全部知识唯一标准，也不把身份设为真值证明。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。切换所问日期事实与经验意义，显示不同证据职责；切换表达与授权问题，显示制度条件检查。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"真实口述史方法规范展示位置、保护与有据批评可共存，不虚构具体访谈成效。"},"openQuestions":["未取得研究入口02.01—02.08所指全部研究原稿；所列思想传统的完整差异和历史采用不能由目录复原。","未开展真实访谈或检验其安全表达条件。"],"taskId":"S-D-02","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第4545—4560行；每节精确范围见sourceRefs","claim_support":["D.02：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"oha-core","title":"OHA Core Principles","url":"https://oralhistory.org/oha-core-principles/","source_type":"primary","version_or_date":"2018原则体系；2026-10-14读取","locator":"编号3、7、8、9","claim_support":["记忆受个人社会语境影响；需关注权力、安全与公开许可"],"limits":["只核方法规范，不认证具体访谈事实或实施效果。"],"access_status":"partially_read"},{"id":"oha-ethics","title":"OHA Statement on Ethics","url":"https://oralhistory.org/oha-statement-on-ethics/","source_type":"primary","version_or_date":"2018原则体系；2026-10-14读取","locator":"Using Oral Sources末两段","claim_support":["应忠实尊重话语及语境；可据准确引用证据提出不同结论"],"limits":["不赋予任一叙述真值特权，也不认证实际研究质量。"],"access_status":"partially_read"},{"id":"oha-adoption","title":"OHA Principles and Best Practices","url":"https://oralhistory.org/principles-and-best-practices-revised-2018/","source_type":"primary","version_or_date":"2018-10","locator":"标题下Adopted October2018及文件列表","claim_support":["该原则体系于2018年10月采纳"],"limits":["仅版本日期，不推断历史思想采用关系。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-D-02/lecture.md","sourcesPath":"/reading-assets/S-D-02/sources.json","sourceSlicePath":"/reading-assets/S-D-02/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-D-02/diagrams.md"}}},"headers":[],"relativePath":"theory/appendix-d/d-02.md","filePath":"theory/appendix-d/d-02.md"}'),l={name:"theory/appendix-d/d-02.md"};function d(p,e,u,h,_,m){const t=a("SectionLesson");return r(),i("div",null,[e[0]||(e[0]=o('<div class="theory-source"><h1 id="section-d-02" tabindex="-1"><span class="xk-num"><span class="xk-num__n">D.02</span><span class="xk-num__gap">　</span></span>知识、概念、语境与认识位置 <a class="header-anchor" href="#section-d-02" aria-label="Permalink to &quot;D.02　知识、概念、语境与认识位置 {#section-d-02}&quot;">​</a></h1><p>正文连接：§2.1—2.7；§4.8；§16.6、16.15。研究入口：02.01—02.08。</p><p>经验、推理、实践、身体经验、文本解释和规范论证各有证明责任。形式推导要公开前提与规则；经验判断要说明观察怎样支持主张；解释性研究要把文本、语境和竞争读法放在一起；规范论证要说明理由与受影响位置。它们可以互相约束，不能被统一压成一个预测成绩。</p><p>证伪、范式与研究纲领提供不同尺度的批评。一个局部反例可能否定某个辅助假设，也可能要求调整对象或测量；是否足以动摇更广理论，要看原命题的范围和依赖。换一个问题可以产生有价值的新研究，但不能把新结果倒填为旧检验成功。实用、可行动、获得共识和为真也不是同一标准。</p><p>语言既描述也可能构成行动：承诺、命名、授予资格和报告事实所需的说话位置、规则与证据不同。一个人说“我同意”可能是真实表达，也可能在特定压力下不足以构成有效授权。理解其话语意义，不能替代对制度条件的检查；语言失配也不能直接诊断人格或智力。</p><p>认识位置影响谁能接近材料、什么问题可被提出、谁的表达更容易被相信。改善听取、翻译和安全表达的条件，可以增加可用知识；被排斥者的发言仍应按具体主张审查，既不先验失格，也不获得自动真值特权。保护性不公开可以与可信核验并存。</p><p>允许不同方法互相纠正，仍需保留它们真正不同的理论承诺。位置影响知识生产不推出对象可被任意制造，理由可能参与因果解释也不取消意义理解的独立任务。可靠日期材料能够纠正一个记忆中的日期，同时保留讲述资格和经历的意义；承认讲述者的地位，不使每一事实命题自动为真。</p><p>专题定位：02.01 经验论与理性论：休谟、笛卡尔等；02.02 证伪、范式与研究纲领：波普尔、库恩、拉卡托斯；02.03 实用主义：皮尔士、詹姆斯、杜威；02.04 实在论、建构论与批判实在论；02.05 现象学：胡塞尔、海德格尔、梅洛-庞蒂；02.06 解释学：狄尔泰、伽达默尔、利科；02.07 语言、概念与语境：维特根斯坦、奥斯汀等；02.08 认识不正义与位置性知识。</p></div>',1)),n(t,{section:"D.02"}),e[1]||(e[1]=c("div",{class:"theory-source"},null,-1))])}const y=s(l,[["render",d]]);export{f as __pageData,y as default};
